create or replace function public.be_approved_tariff_lookup_key(p_value text) returns text language plpgsql stable set search_path=pg_catalog,public,pg_temp as $fn$
declare k text; matched text;
begin
k:=regexp_replace(regexp_replace(regexp_replace(lower(btrim(p_value)), '[[:space:]]*(township|မြို့နယ်)$', '', 'i'),'\(royal\)','','g'),'[[:space:]]+','','g');
